657			isExporting = true;
658			try {
659				// #{#exp4b} Criterion 2: Export filtered expenses
660				const csvContent = csvService.exportExpensesToCSV(filteredExpenses);
661	
662				// #{#edf2a} Criterion 2: Generate filename based on current filters
663				// Date filter takes precedence in filename
664				let filename: string;
665	
666				if (urlDateFrom && urlDateTo) {
667					filename = `expenses_${urlDateFrom}_to_${urlDateTo}.csv`;
668				} else if (urlDateFrom) {
669					filename = `expenses_from_${urlDateFrom}.csv`;
670				} else if (urlDateTo) {
671					filename = `expenses_to_${urlDateTo}.csv`;
672				} else if (showUncategorizedOnly) {
673					filename = 'expenses_uncategorized.csv';
674				} else if (selectedCategoryIds.length === 1) {
675					const category = categories.find((c) => c.id === selectedCategoryIds[0]);
676					const catName = category?.name.toLowerCase().replace(/\s+/g, '_') || 'filtered';
677					filename = `expenses_${catName}.csv`;
678				} else if (selectedCategoryIds.length > 1) {
679					filename = 'expenses_multiple_categories.csv';
680				} else {
681					filename = csvService.generateFilename('all');
682				}
683	
684				// #{#exp3a} Criterion 1: Download CSV
685				csvService.downloadCSV(csvContent, filename);
686	
687				// #{#exp3b} Criterion 3: Success feedback
688				showToast(
689					`CSV exported successfully: ${filteredExpenses.length} expense${filteredExpenses.length !== 1 ? 's' : ''}`,
690					'success'
691				);
692			} catch (err) {
693				// #{#exp3b} Criterion 4: Error feedback
694				console.error('Error exporting CSV:', err);
695				showToast(
696					`Failed to export CSV: ${err instanceof Error ? err.message : 'Unknown error'}`,
697					'error'
698				);
699			} finally {
700				isExporting = false;
701			}
702		}
