799		// #{#sec1a} Signed URL cache for receipt images
800		let signedUrls: Record<string, string> = $state({});
801	
802		// #{#sec1a} Load signed URLs whenever expenses change
803		// Uses untrack to read signedUrls without creating a reactive loop
804		$effect(() => {
805			const paths = expenses
806				.map((e) => e.receipt_image_path)
807				.filter((p): p is string => !!p);
808			untrack(() => loadSignedUrls(paths));
809		});
810	
811		async function loadSignedUrls(paths: string[]) {
812			const cached = signedUrls;
813			const newUrls: Record<string, string> = {};
814			const missing: string[] = [];
815			for (const path of paths) {
816				if (cached[path]) newUrls[path] = cached[path];
817				else missing.push(path);
818			}
819			// #{#sec1c} Sign all uncached paths in one batched request instead of one per path.
820			if (missing.length > 0) {
821				Object.assign(newUrls, await getSignedReceiptUrls(missing));
822			}
823			signedUrls = newUrls;
824		}
825	
826		function getImageUrl(path: string | null): string | null {
827			if (!path) return null;
828			return signedUrls[path] ?? null;
829		}
