448		// #{#spl2a} Open split modal for a receipt
449		function openSplitModal(receipt: ReceiptRow) {
450			splittingReceipt = receipt;
451			splitAmount = '';
452			splitDate = receipt.transaction_date ?? ''; // #{#spl7b} Default to original date
453			splitError = null;
454			showSplitModal = true;
