457		// #{#spl2a} Close split modal
458		function closeSplitModal() {
459			showSplitModal = false;
460			splittingReceipt = null;
461			splitAmount = '';
462			splitDate = '';
463			splitError = null;
464			isSplitting = false;
465		}
