467		// #{#spl2b} Validate split amount in real-time
468		function getSplitValidationError(amountStr: string, receiptTotal: number | null): string | null {
469			if (!amountStr) return null; // Empty is not an error (just disables button)
470			const amount = parseFloat(amountStr);
471			if (isNaN(amount) || !isFinite(amount)) return 'Please enter a valid amount';
472			if (amount <= 0) return 'Split amount must be greater than zero';
473			if (receiptTotal == null || receiptTotal <= 0) return 'Receipt has no amount to split';
474			if (amount >= receiptTotal) return 'Split amount must be less than the receipt total';
475			if (Math.round(amount * 100) !== amount * 100) return 'Amount can have at most 2 decimal places';
476			return null;
477		}
478	
479		// #{#spl2b} Derived validation for split modal
480		let splitValidationError = $derived(
481			getSplitValidationError(splitAmount, splittingReceipt?.total_amount ?? null)
482		);
483	
484		let splitAmountParsed = $derived(parseFloat(splitAmount));
485		let splitRemainingAmount = $derived(
486			splittingReceipt?.total_amount != null && !isNaN(splitAmountParsed)
487				? Math.round((splittingReceipt.total_amount - splitAmountParsed) * 100) / 100
488				: null
489		);
490	
491		let isSplitValid = $derived(
492			splitAmount !== '' && splitValidationError === null && (splitRemainingAmount ?? 0) > 0
493		);
494	
495		// #{#spl2a} Execute the split
496		async function executeSplit() {
497			if (!splittingReceipt || !isSplitValid) return;
498	
499			isSplitting = true;
500			splitError = null;
501	
502			try {
503				// #{#spl7b} Pass splitDate if different from original
504				const dateOverride =
505					splitDate && splitDate !== splittingReceipt.transaction_date ? splitDate : undefined;
506				await ReceiptService.get().splitReceipt(
507					splittingReceipt.id,
508					splitAmountParsed,
509					dateOverride
510				);
511				successMessage = `Receipt split: $${splitAmountParsed.toFixed(2)} + $${splitRemainingAmount?.toFixed(2)}`;
512				setTimeout(() => {
513					successMessage = null;
514				}, 3000);
515				closeSplitModal();
516				await loadReconciliation();
517			} catch (e: any) {
518				splitError = e?.message ?? 'Failed to split receipt';
519			} finally {
520				isSplitting = false;
521			}
522		}
