524		// #{#spl3a} #{#spl3b} Compute split group info for display
525		function getSplitGroupInfo(
526			receipt: ReceiptRow,
527			allRows: ReconciliationDisplayRow[]
528		): { index: number; total: number; groupAmounts: number[] } | null {
529			const groupId = receipt.split_group_id;
530			if (!groupId) return null;
531	
532			// Find all receipts in this split group from all display rows
533			const groupReceipts: ReceiptRow[] = [];
534			for (const row of allRows) {
535				if (row.receipt?.split_group_id === groupId) {
536					groupReceipts.push(row.receipt);
537				}
538			}
539	
540			if (groupReceipts.length <= 1) return null;
541	
542			// Sort by created_at for consistent ordering
543			groupReceipts.sort((a, b) => a.created_at.localeCompare(b.created_at));
544			const index = groupReceipts.findIndex((r) => r.id === receipt.id);
545	
546			return {
547				index: index + 1,
548				total: groupReceipts.length,
549				groupAmounts: groupReceipts.map((r) => r.total_amount ?? 0)
550			};
551		}
