161		async function loadSignedUrls(paths: string[]) {
162			const cached = signedUrls;
163			const newUrls: Record<string, string> = {};
164			const missing: string[] = [];
165			for (const path of paths) {
166				if (cached[path]) newUrls[path] = cached[path];
167				else missing.push(path);
168			}
169			// #{#sec1c} Sign all uncached paths in one batched request instead of one per path.
170			if (missing.length > 0) {
171				Object.assign(newUrls, await getSignedReceiptUrls(missing));
172			}
173			signedUrls = newUrls;
174		}
