299		function applyClientFilters(rcts: ReceiptRow[]): ReceiptRow[] {
300			// #{#dup5a} Pre-compute duplicate IDs when filter is active
301			let dupeIds: Set<string> | null = null;
302			if (filterDuplicates) {
303				const dupes = detectDuplicates(rcts);
304				dupeIds = new Set<string>();
305				for (const ids of dupes.values()) {
306					for (const id of ids) dupeIds.add(id);
307				}
308			}
309	
310			return rcts.filter((r) => {
311				// #{#dtv3a} Filter by suspicious_date (Needs Review)
312				if (filterNeedsReview && !r.suspicious_date) return false;
313	
314				// #{#dup5a} Filter by duplicate status
315				if (filterDuplicates && dupeIds && !dupeIds.has(r.id)) return false;
316	
317				// #{#sdf1b} Filter by date range using URL parameters
318				if (urlDateFrom && r.transaction_date && r.transaction_date < urlDateFrom) return false;
319				if (urlDateTo && r.transaction_date && r.transaction_date > urlDateTo) return false;
320	
321				// Filter by merchant name (local state)
322				if (filterMerchant) {
323					const merchantSearch = filterMerchant.toLowerCase();
324					const merchant = (r.merchant_name || '').toLowerCase();
325					if (!merchant.includes(merchantSearch)) return false;
326				}
327	
328				// Filter by amount range (local state)
329				if (filterAmountMin && r.total_amount !== null) {
330					const minAmount = parseFloat(filterAmountMin);
331					if (!isNaN(minAmount) && r.total_amount < minAmount) return false;
332				}
333				if (filterAmountMax && r.total_amount !== null) {
334					const maxAmount = parseFloat(filterAmountMax);
335					if (!isNaN(maxAmount) && r.total_amount > maxAmount) return false;
336				}
337	
338				return true;
339			});
340		}
