342		function applyFilterValues(): void {
343			// #{#sdf2a} Update URL with date filters
344			const params = new URLSearchParams($page.url.searchParams);
345	
346			if (tempFilterDateFrom) params.set('dateFrom', tempFilterDateFrom);
347			else params.delete('dateFrom');
348	
349			if (tempFilterDateTo) params.set('dateTo', tempFilterDateTo);
350			else params.delete('dateTo');
351	
352			goto(`${$page.url.pathname}?${params.toString()}`, { replaceState: true, keepFocus: true });
353	
354			// Apply non-date filters locally
355			filterMerchant = tempFilterMerchant;
356			filterAmountMin = tempFilterAmountMin;
357			filterAmountMax = tempFilterAmountMax;
358		}
