360		function clearClientFilters(): void {
361			// #{#sdf2a} Clear URL date filters
362			const params = new URLSearchParams($page.url.searchParams);
363			params.delete('dateFrom');
364			params.delete('dateTo');
365			goto(`${$page.url.pathname}?${params.toString()}`, { replaceState: true, keepFocus: true });
366	
367			// Clear local filters
368			tempFilterMerchant = '';
369			tempFilterAmountMin = '';
370			tempFilterAmountMax = '';
371			filterMerchant = '';
372			filterAmountMin = '';
373			filterAmountMax = '';
374	
375			// #{#dtv3a} Clear Needs Review filter
376			filterNeedsReview = false;
377	
378			// #{#dup5a} Clear Duplicates filter
379			filterDuplicates = false;
380		}
