382		let receipts = $derived((() => {
383			// Explicitly depend on all filter variables (URL-based date filters + local filters)
384			const deps = [urlDateFrom, urlDateTo, filterMerchant, filterAmountMin, filterAmountMax, filterDuplicates];
385			const filtered = applyClientFilters(allReceipts);
386			console.log('[DEBUG] Filtering receipts:', {
387				allReceiptsCount: allReceipts.length,
388				filteredCount: filtered.length,
389				filters: { urlDateFrom, urlDateTo, filterMerchant, filterAmountMin, filterAmountMax, filterNeedsReview, filterDuplicates }
390			});
391			return filtered;
392		})());
393	
394		// #{#dup1b} #{#dup2b} Detect duplicates on filtered receipts
395		let duplicateGroups = $derived(detectDuplicates(receipts));
396	
397		// #{#dup5a} Detect duplicates on ALL receipts for badge count
398		let allDuplicateGroups = $derived(detectDuplicates(allReceipts));
399		let duplicateReceiptCount = $derived(
400			Array.from(allDuplicateGroups.values()).reduce((sum, ids) => sum + ids.length, 0)
401		);
402	
403		let hasActiveFilters = $derived(
404			urlDateFrom ||
405			urlDateTo ||
406			filterMerchant ||
407			filterAmountMin ||
408			filterAmountMax ||
409			filterNeedsReview ||
410			filterDuplicates
