414		function toggleSelection(id: string): void {
415			if (selectedReceiptIds.has(id)) {
416				selectedReceiptIds.delete(id);
417			} else {
418				selectedReceiptIds.add(id);
419			}
420			selectedReceiptIds = new Set(selectedReceiptIds); // Trigger reactivity
421		}
