431		// #{#blk4b} Clear selection
432		function clearSelection(): void {
433			selectedReceiptIds = new Set<string>();
434		}
435	
436		// #{#blk2a} Check if all visible receipts are selected
437		let isAllSelected = $derived(receipts.length > 0 && receipts.every((r) => selectedReceiptIds.has(r.id)));
438	
439		// #{#blk1a} Check if some (but not all) receipts are selected
440		let isIndeterminate = $derived(
