451		// #{#blk3a} #{#blk3b} Execute bulk delete with optimistic update
452		async function executeBulkDelete(): Promise<void> {
453			isDeleting = true;
454			showDeleteConfirm = false;
455			errorMessage = null;
456			successMessage = null;
457	
458			// Optimistic update - remove from UI immediately
459			const idsToDelete = Array.from(selectedReceiptIds);
460			const originalReceipts = [...allReceipts];
461	
462			// #{#blk3b} Optimistic UI update
463			allReceipts = allReceipts.filter((r) => !selectedReceiptIds.has(r.id));
464	
465			try {
466				// #{#blk3a} Call bulk delete service
467				await ReceiptService.get().bulkDeleteReceipts(idsToDelete);
468	
469				// #{#blk6b} Success feedback
470				successMessage = `Successfully deleted ${idsToDelete.length} receipt${idsToDelete.length === 1 ? '' : 's'}`;
471				clearSelection();
472	
473				// Auto-dismiss success message after 4 seconds
474				setTimeout(() => {
475					successMessage = null;
476				}, 4000);
477			} catch (e: any) {
478				// #{#blk3b} Rollback on failure
479				allReceipts = originalReceipts;
480				errorMessage = e?.message ?? 'Failed to delete receipts. Please try again.';
481	
482				// Keep error message visible longer
483				setTimeout(() => {
484					errorMessage = null;
485				}, 8000);
486			} finally {
487				isDeleting = false;
488			}
489		}
490	
491		// #{#blk1b} Clear invalid selections when receipts are deleted individually
492		$effect(() => {
493			const validIds = new Set(allReceipts.map((r) => r.id));
494			const filtered = new Set(Array.from(selectedReceiptIds).filter((id) => validIds.has(id)));
495			if (filtered.size !== selectedReceiptIds.size) {
496				selectedReceiptIds = filtered;
497			}
498		});
