90		validateFormat(csvContent: string): boolean {
91			try {
92				csvContent = this.removeBOM(csvContent);
93				const rows = this.parseCSV(csvContent);
94				if (rows.length === 0) return false;
95	
96				const header = rows[0];
97				// Check for EQ Bank-specific columns
98				// Must have exactly 3 or 4 columns
99				if (header.length < 3 || header.length > 4) return false;
100	
101				// Accept either "Date" or "Transfer date" for the date column
102				const hasDate = header.some(
103					(h) => h.toLowerCase() === 'date' || h.toLowerCase() === 'transfer date'
104				);
105				const hasDescription = header.some((h) => h.toLowerCase() === 'description');
106				const hasAmount = header.some((h) => h.toLowerCase() === 'amount');
107	
108				// Should NOT have columns like "Type", "Card Holder Name", "Time" (which are PC Financial)
109				const hasPCFinancialColumns = header.some(
110					(h) =>
111						h.toLowerCase() === 'type' ||
112						h.toLowerCase().includes('card holder') ||
