63					month = parseInt(parts[1]) - 1;
64					day = parseInt(parts[2]);
65				}
66	
67				const dayStr = String(day).padStart(2, '0');
68				return `${MONTHS[month]} ${dayStr}, ${year}`;
69			} catch {
